// ==== financas.js ====
// static\js\modules\pasta_financas\financas.js
// ==========================================================
// FINANÇAS - MAIN
// ==========================================================

(function() {
    'use strict';

    /**
     * Recarrega a tabela de finanças via HTMX mantendo os filtros atuais.
     * Busca a URL do data-attribute do container ou usa '/financas' como fallback.
     */
    function recarregarTabelaFinancas() {
        var tabelaContainer = document.getElementById('tabela-container');
        if (!tabelaContainer) return;

        // Recupera a URL configurada no data-url-refresh do container, ou usa a rota principal
        var urlRefresh = tabelaContainer.dataset.urlRefresh || '/financas';

        htmx.ajax('GET', urlRefresh, {
            target: '#tabela-container',
            swap: 'outerHTML'
        });
    }

    /**
     * Inicializa os ouvintes de eventos da página.
     */
    function init() {
        // Escuta evento personalizado enviado pelo backend (Response Header: HX-Trigger: atualizarTabelaFinancas)
        document.body.addEventListener('atualizarTabelaFinancas', function() {
            recarregarTabelaFinancas();
        });

        // Re-inicializa componentes após troca do fragmento HTMX na tabela
        document.addEventListener('htmx:afterSwap', function(evento) {
            if (evento.detail.target && evento.detail.target.id === 'tabela-container') {
                // Eventos de clique com o botão direito ou inicializações de UI da tabela podem vir aqui
                if (typeof window.inicializarMenuContexto === 'function') {
                    window.inicializarMenuContexto();
                }
            }
        });
    }

    // Exporta a função para escopo global para acionamento direto via onclick ou outros modais
    window.recarregarTabelaFinancas = recarregarTabelaFinancas;

    // Executar após o carregamento da árvore DOM
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    console.log('✅ FINANÇAS - MAIN carregado!');

})();

// ==== api-transacao.js ====
(function() {
    'use strict';
    window.ApiTransacao = {
        async enviar(url, formData) {
            const res = await fetch(url || window.location.href, {
                method: 'POST',
                body: formData,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            });
            const data = await res.json();
            return { ok: res.ok, data };
        }
    };
})();

// ==== formatadores.js ====
// static\js\modules\pasta_financas\core\formatadores.js
(function() {
    'use strict';
    window.FormatadoresFinancas = {
        mascaraMoeda(input) {
            var value = input.value.replace(/\D/g, '');
            if (!value) return '0,00';
            var floatVal = (parseFloat(value) / 100).toFixed(2);
            var parts = floatVal.split('.');
            parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
            return parts.join(',');
        },
        paraFloat(strValor) {
            return parseFloat((strValor || '0,00').replace(/\./g, '').replace(',', '.')) || 0;
        }
    };
})();

// ==== TransacaoForm.js ====
// static/js/modules/pasta_financas/core/TransacaoForm.js
// ==========================================================
// TransacaoForm - Classe única para os modais Nova e Editar
// ==========================================================

(function() {
    'use strict';

    function TransacaoForm(formEl, options) {
        if (!formEl) throw new Error('TransacaoForm: formEl obrigatório');

        this.form = formEl;
        this.options = options || {};
        this.mode = this.options.mode || 'create';
        this.onSubmitSuccess = this.options.onSubmitSuccess || null;
        this.onSubmitError = this.options.onSubmitError || null;

        // Pega o modal pai pra acessar os totalizadores do footer
        var modal = formEl.closest('.fin-modal-overlay') || formEl.closest('body');

        // Elementos internos (escopados — sem colisão)
        this.el = {
            totalOriginal:  modal.querySelector('.js-total-original'),
            somaParcelas:   modal.querySelector('.js-soma-parcelas'),
            diferenca:      modal.querySelector('.js-diferenca-valor'),
            tipoHidden:        formEl.querySelector('.js-tipo-hidden'),
            tipoBtns:          formEl.querySelectorAll('.js-tipo-btn'),
            descricao:         formEl.querySelector('.js-descricao'),
            categoria:         formEl.querySelector('.js-categoria'),
            valorTotal:        formEl.querySelector('.js-valor-total'),
            totalParcelas:     formEl.querySelector('.js-total-parcelas'),
            dataEmissao:       formEl.querySelector('.js-data-emissao'),
            dataVencimento:    formEl.querySelector('.js-data-vencimento'),
            intervaloDias:     formEl.querySelector('.js-intervalo-dias'),
            parcelasConfig:    formEl.querySelector('.js-parcelas-config'),
            parcelasWrapper:   formEl.querySelector('.js-parcelas-wrapper'),
            parcelasBody:      formEl.querySelector('.js-parcelas-body'),
            btnDistribuir:     formEl.querySelector('.js-btn-distribuir')
        };

        // Estado interno das parcelas em modo edit (fonte da verdade do front)
        this._parcelasCarregadas = null;
        this._datasEditadasManualmente = false;

        this._bind();
    }

    // ==========================================================
    // EVENTOS
    // ==========================================================
    TransacaoForm.prototype._bind = function() {
        var self = this;

        // Tipo (receita / despesa)
        this.el.tipoBtns.forEach(function(btn) {
            btn.addEventListener('click', function() {
                if (btn.disabled) return;   // 🔥 respeita o disabled
                self.el.tipoBtns.forEach(function(b) { b.classList.remove('active'); });
                btn.classList.add('active');
                var tipo = btn.dataset.tipo;
                if (self.el.tipoHidden) self.el.tipoHidden.value = (tipo === 'vazio') ? '' : tipo;
            });
        });

        if (this.el.valorTotal) {
            this.el.valorTotal.addEventListener('input', function(e) {
                if (window.FormatadoresFinancas) {
                    e.target.value = window.FormatadoresFinancas.mascaraMoeda(e.target);
                }
                self._redistribuirValores();
                self._atualizarTotalizadores();
            });
        }

        // Escuta mudanças de valores das parcelas (delegation)
        if (this.el.parcelasBody) {
            this.el.parcelasBody.addEventListener('input', function(e) {
                if (e.target && e.target.classList.contains('js-parcela-valor')) {
                    self._atualizarTotalizadores();
                }
            });
        }

        // Nº de parcelas
        if (this.el.totalParcelas) {
            this.el.totalParcelas.addEventListener('input', function() {
                self._onTotalParcelasChange();
            });
        }

        // Botão "Distribuir igualmente"
        if (this.el.btnDistribuir) {
            this.el.btnDistribuir.addEventListener('click', function() {
                self.distribuirIgualmente();
            });
        }

        // Intervalo entre parcelas — recalcula datas SE o usuário não editou manualmente
        if (this.el.intervaloDias) {
            this.el.intervaloDias.addEventListener('input', function() {
                self._recalcularDatasSeNaoEditadas();
            });
            this.el.intervaloDias.addEventListener('change', function() {
                self._recalcularDatasSeNaoEditadas();
            });
        }

        // Detecta edição manual em qualquer data de parcela (event delegation)
        if (this.el.parcelasBody) {
            this.el.parcelasBody.addEventListener('change', function(e) {
                if (e.target && e.target.classList.contains('js-parcela-data')) {
                    self._datasEditadasManualmente = true;
                    console.log('🔓 Modo manual ativado — intervalo não vai mais sobrescrever');
                }
            });
            this.el.parcelasBody.addEventListener('input', function(e) {
                if (e.target && e.target.classList.contains('js-parcela-data')) {
                    self._datasEditadasManualmente = true;
                }
            });
        }

        // Data de emissão — recalcula datas das parcelas SE o usuário não editou manualmente
        if (this.el.dataEmissao) {
            this.el.dataEmissao.addEventListener('change', function() {
                self._recalcularDatasSeNaoEditadas();
            });
        }
    };

    TransacaoForm.prototype._redistribuirValores = function() {
        var rows = this.el.parcelasBody ? this.el.parcelasBody.querySelectorAll('tr') : [];
        if (rows.length <= 1) return;

        var valorTotal = window.FormatadoresFinancas
            ? window.FormatadoresFinancas.paraFloat(this.el.valorTotal.value)
            : 0;
        var n = rows.length;
        var valorBase = Math.floor((valorTotal / n) * 100) / 100;
        var resto = parseFloat((valorTotal - (valorBase * n)).toFixed(2));

        rows.forEach(function(row, idx) {
            var input = row.querySelector('.js-parcela-valor');
            if (!input) return;
            var v = (idx === 0) ? (valorBase + resto) : valorBase;
            input.value = v.toFixed(2).replace('.', ',');
        });
    };

    TransacaoForm.prototype._onTotalParcelasChange = function() {
        this._parcelasCarregadas = null;
        this._datasEditadasManualmente = false;
        this._toggleDataVencimento();
        this._renderParcelasDoZero();
        this._atualizarTotalizadores();
    };

    TransacaoForm.prototype._toggleDataVencimento = function() {
        var total = parseInt(this.el.totalParcelas ? this.el.totalParcelas.value : 1) || 1;
        var grupo = this.el.dataVencimento ? this.el.dataVencimento.closest('.form-group') : null;

        if (grupo) {
            grupo.style.display = (total > 1) ? 'none' : '';
        }
    };

    TransacaoForm.prototype._recalcularDatasSeNaoEditadas = function() {
        if (this._datasEditadasManualmente) return;

        var rows = this.el.parcelasBody ? this.el.parcelasBody.querySelectorAll('tr') : [];
        if (rows.length <= 1) return;

        var dataEmissao = this.el.dataEmissao ? this.el.dataEmissao.value : '';
        if (!dataEmissao) return;

        var intervalo = this.el.intervaloDias ? (parseInt(this.el.intervaloDias.value) || 30) : 30;
        var dataBase = new Date(dataEmissao + 'T00:00:00');

        rows.forEach(function(row, idx) {
            var inputData = row.querySelector('.js-parcela-data');
            if (!inputData) return;

            var d = new Date(dataBase.getTime());
            d.setDate(d.getDate() + ((idx + 1) * intervalo));

            var ano = d.getFullYear();
            var mes = String(d.getMonth() + 1).padStart(2, '0');
            var dia = String(d.getDate()).padStart(2, '0');
            inputData.value = ano + '-' + mes + '-' + dia;
        });
    };

    // ==========================================================
    // API PÚBLICA: setData (usado no modo edit)
    // ==========================================================
    TransacaoForm.prototype.setData = function(data) {
        if (!data) return;

        var self = this;

        if (this.el.descricao)    this.el.descricao.value = data.descricao || '';

        if (this.el.valorTotal) {
            this.el.valorTotal.value = parseFloat(data.valor_total || 0).toLocaleString('pt-BR', {
                minimumFractionDigits: 2, maximumFractionDigits: 2
            });
        }

        if (this.el.dataEmissao)    this.el.dataEmissao.value = data.data_emissao || '';
        if (this.el.dataVencimento) this.el.dataVencimento.value = data.data_vencimento || '';
        if (this.el.categoria)      this.el.categoria.value = data.categoria_id || '';
        if (this.el.totalParcelas)  this.el.totalParcelas.value = data.total_parcelas || 1;
        if (this.el.tipoHidden)     this.el.tipoHidden.value = data.tipo || '';

        this.el.tipoBtns.forEach(function(btn) {
            btn.classList.remove('active');
            if (btn.dataset.tipo === data.tipo) btn.classList.add('active');
        });

        var parcelas = (data.parcelas || []).map(function(p, i) {
            return {
                numero: p.numero_parcela || (i + 1),
                data_vencimento: p.data_vencimento || '',
                valor: p.valor || 0
            };
        });

        this._parcelasCarregadas = (parcelas.length > 0) ? parcelas : null;
        this._datasEditadasManualmente = false;
        this._toggleDataVencimento();

        if (this._parcelasCarregadas && this._parcelasCarregadas.length > 1) {
            this._renderParcelas(this._parcelasCarregadas);
        } else {
            this._renderParcelasDoZero();
        }
        this._atualizarTotalizadores();

        // 🔥 Bloqueia Nº Parcelas no editar (quantidade é imutável)
        if (this.el.totalParcelas) {
            this.el.totalParcelas.readOnly = true;
            this.el.totalParcelas.style.opacity = '0.6';
            this.el.totalParcelas.style.cursor = 'not-allowed';
            this.el.totalParcelas.title = 'Quantidade de parcelas não pode ser alterada. Exclua e crie novamente.';
        }

        // 🔥 Bloqueia botões de tipo no editar (tipo é imutável)
        this.el.tipoBtns.forEach(function(btn) {
            btn.disabled = true;
            btn.style.opacity = '0.5';
            btn.style.cursor = 'not-allowed';
            btn.title = 'Tipo não pode ser alterado. Exclua e crie novamente.';
        });
    };

    // ==========================================================
    // API PÚBLICA: getData (serializa pro POST)
    // ==========================================================
    TransacaoForm.prototype.getData = function() {
        var tipo = this.el.tipoHidden ? this.el.tipoHidden.value : '';
        var valorTotal = this.el.valorTotal && window.FormatadoresFinancas
            ? window.FormatadoresFinancas.paraFloat(this.el.valorTotal.value)
            : 0;
        var totalParcelas = this.el.totalParcelas ? (parseInt(this.el.totalParcelas.value) || 1) : 1;

        var parcelas = [];
        if (this.el.parcelasBody) {
            this.el.parcelasBody.querySelectorAll('tr').forEach(function(row, idx) {
                var v = row.querySelector('.js-parcela-valor');
                var d = row.querySelector('.js-parcela-data');
                if (v && d) {
                    parcelas.push({
                        numero: idx + 1,
                        valor: window.FormatadoresFinancas
                            ? window.FormatadoresFinancas.paraFloat(v.value)
                            : parseFloat(v.value) || 0,
                        vencimento: d.value
                    });
                }
            });
        }

        return {
            tipo: tipo,
            descricao: this.el.descricao ? this.el.descricao.value.trim() : '',
            categoria_id: this.el.categoria ? this.el.categoria.value : '',
            valor_total: valorTotal,
            data_emissao: this.el.dataEmissao ? this.el.dataEmissao.value : '',
            data_vencimento: this.el.dataVencimento ? this.el.dataVencimento.value : '',

            primeiroVencimento: (function() {
                var primeiraData = parcelas.length > 0 ? parcelas[0].vencimento : '';
                return primeiraData || (this.el.dataVencimento ? this.el.dataVencimento.value : '');
            }).call(this),

            intervaloDias: this.el.intervaloDias ? (parseInt(this.el.intervaloDias.value) || 30) : 30,
            total_parcelas: totalParcelas,
            parcelas: parcelas
        };
    };

    // ==========================================================
    // API PÚBLICA: reset
    // ==========================================================
    TransacaoForm.prototype.reset = function() {
        this.form.reset();
        this._parcelasCarregadas = null;
        this._datasEditadasManualmente = false;

        if (this.el.tipoHidden) this.el.tipoHidden.value = '';
        this.el.tipoBtns.forEach(function(b) { b.classList.remove('active'); });

        if (this.el.valorTotal) this.el.valorTotal.value = '0,00';
        if (this.el.totalParcelas) this.el.totalParcelas.value = '1';
        if (this.el.parcelasConfig) this.el.parcelasConfig.style.display = 'none';
        if (this.el.parcelasWrapper) this.el.parcelasWrapper.style.display = 'none';
        if (this.el.parcelasBody) {
            this.el.parcelasBody.innerHTML =
                '<tr><td colspan="3" class="parcelas-vazio">Selecione mais de 1 parcela</td></tr>';
        }
        this._toggleDataVencimento();
        this._atualizarTotalizadores();

        // 🔥 Desbloqueia Nº Parcelas no criar
        if (this.el.totalParcelas) {
            this.el.totalParcelas.readOnly = false;
            this.el.totalParcelas.style.opacity = '';
            this.el.totalParcelas.style.cursor = '';
            this.el.totalParcelas.title = '';
        }

        // 🔥 Desbloqueia botões de tipo no criar (exceto o "Sel.")
        this.el.tipoBtns.forEach(function(btn) {
            if (btn.dataset.tipo === 'vazio') return;   // ignora o "Sel."
            btn.disabled = false;
            btn.style.opacity = '';
            btn.style.cursor = '';
            btn.title = '';
        });
    };

    // ==========================================================
    // API PÚBLICA: submit
    // ==========================================================
    TransacaoForm.prototype.submit = function(url) {
        var self = this;
        var data = this.getData();

        if (!data.tipo) {
            if (window.Notificacao) window.Notificacao.aviso('Selecione o tipo (Receita ou Despesa).');
            return Promise.reject(new Error('tipo vazio'));
        }
        if (!data.descricao) {
            if (window.Notificacao) window.Notificacao.aviso('Descrição é obrigatória.');
            return Promise.reject(new Error('descricao vazia'));
        }
        if (data.valor_total <= 0) {
            if (window.Notificacao) window.Notificacao.aviso('Informe um valor maior que zero.');
            return Promise.reject(new Error('valor invalido'));
        }
        
        // 🔥 NOVA VALIDAÇÃO: soma das parcelas deve bater com o valor total
        if (data.parcelas && data.parcelas.length > 1) {
            var soma = data.parcelas.reduce(function(acc, p) {
                return acc + p.valor;
            }, 0);
            soma = parseFloat(soma.toFixed(2));

            if (Math.abs(data.valor_total - soma) > 0.01) {
                var msg = 'A soma das parcelas (R$ ' + soma.toFixed(2).replace('.', ',') +
                        ') precisa ser igual ao Valor Total (R$ ' + data.valor_total.toFixed(2).replace('.', ',') + ').';
                if (window.Notificacao) window.Notificacao.erro(msg);
                return Promise.reject(new Error('soma_nao_bate'));
            }
        }

        var body = this.mode === 'create'
            ? this._toFormData(data)
            : JSON.stringify(data);

        var headers = { 'X-Requested-With': 'XMLHttpRequest' };
        if (this.mode !== 'create') headers['Content-Type'] = 'application/json';

        return fetch(url, {
            method: 'POST',
            headers: headers,
            body: body
        })
        .then(function(r) { return r.json().then(function(j) { return { ok: r.ok, data: j }; }); })
        .then(function(res) {
            if (!res.ok || res.data.success === false) {
                var msg;
                if (res.data.errors && res.data.errors.length > 0) {
                    msg = res.data.errors[0].mensagem;
                } else {
                    msg = res.data.error || res.data.message || 'Erro ao salvar.';
                }
                if (self.onSubmitError) self.onSubmitError(msg);
                else if (window.Notificacao) window.Notificacao.erro(msg);
                throw new Error(msg);
            }

            // 🔥 ADICIONA ISSO:
            if (self.onSubmitSuccess) self.onSubmitSuccess(res.data);
            return res.data;
        });
    };

    // ==========================================================
    // RENDERIZAÇÃO DE PARCELAS
    // ==========================================================
    TransacaoForm.prototype._renderParcelas = function(lista) {
        if (!this.el.parcelasBody) return;

        if (this.el.parcelasConfig) this.el.parcelasConfig.style.display = 'block';
        if (this.el.parcelasWrapper) this.el.parcelasWrapper.style.display = 'block';

        var html = '';
        lista.forEach(function(p, index) {
            var num = p.numero || (index + 1);
            var dataVenc = p.data_vencimento || '';
            var val = typeof p.valor === 'number'
                ? p.valor.toFixed(2).replace('.', ',')
                : (p.valor || '0,00');

            html += '<tr>' +
                '<td class="parcelas-td-num"><span class="badge-parcela-num">' + num + '</span></td>' +
                '<td><input type="text" class="form-control form-control-sm parcela-valor js-parcela-valor" value="' + val + '"></td>' +
                '<td><input type="date" class="form-control form-control-sm parcela-data js-parcela-data" value="' + dataVenc + '"></td>' +
                '</tr>';
        });
        this.el.parcelasBody.innerHTML = html;
        this._atualizarTotalizadores();
    };

    TransacaoForm.prototype._renderParcelasDoZero = function() {
        if (!this.el.totalParcelas || !this.el.parcelasBody) return;

        var numParcelas = parseInt(this.el.totalParcelas.value) || 1;

        if (numParcelas <= 1) {
            if (this.el.parcelasConfig) this.el.parcelasConfig.style.display = 'none';
            if (this.el.parcelasWrapper) this.el.parcelasWrapper.style.display = 'none';
            this.el.parcelasBody.innerHTML =
                '<tr><td colspan="3" class="parcelas-vazio">Selecione mais de 1 parcela</td></tr>';
            this._atualizarTotalizadores();
            return;
        }

        if (this._parcelasCarregadas && this._parcelasCarregadas.length === numParcelas) {
            this._renderParcelas(this._parcelasCarregadas);
            return;
        }

        if (this.el.parcelasConfig) this.el.parcelasConfig.style.display = 'block';
        if (this.el.parcelasWrapper) this.el.parcelasWrapper.style.display = 'block';

        var valorTotal = 0;
        if (this.el.valorTotal) {
            valorTotal = window.FormatadoresFinancas
                ? window.FormatadoresFinancas.paraFloat(this.el.valorTotal.value)
                : 0;
        }

        var valorBase = Math.floor((valorTotal / numParcelas) * 100) / 100;
        var resto = parseFloat((valorTotal - (valorBase * numParcelas)).toFixed(2));

        var dataEmissao = this.el.dataEmissao ? this.el.dataEmissao.value : '';
        var intervalo = this.el.intervaloDias ? (parseInt(this.el.intervaloDias.value) || 30) : 30;
        var dataBase = dataEmissao ? new Date(dataEmissao + 'T00:00:00') : new Date();

        var html = '';

        for (var i = 1; i <= numParcelas; i++) {
            var valorParcela = (i === 1) ? (valorBase + resto) : valorBase;

            var dataParcela = new Date(dataBase.getTime());
            dataParcela.setDate(dataParcela.getDate() + (i * intervalo));

            var ano = dataParcela.getFullYear();
            var mes = String(dataParcela.getMonth() + 1).padStart(2, '0');
            var dia = String(dataParcela.getDate()).padStart(2, '0');
            var dataFmt = ano + '-' + mes + '-' + dia;

            html += '<tr>' +
                '<td class="parcelas-td-num"><span class="badge-parcela-num">' + i + '</span></td>' +
                '<td><input type="text" class="form-control form-control-sm parcela-valor js-parcela-valor" value="' + valorParcela.toFixed(2).replace('.', ',') + '"></td>' +
                '<td><input type="date" class="form-control form-control-sm parcela-data js-parcela-data" value="' + dataFmt + '"></td>' +
                '</tr>';
        }
        this.el.parcelasBody.innerHTML = html;
        this._atualizarTotalizadores();
    };

    // ==========================================================
    // API PÚBLICA: distribuirIgualmente
    // ==========================================================
    TransacaoForm.prototype.distribuirIgualmente = function() {
        var rows = this.el.parcelasBody ? this.el.parcelasBody.querySelectorAll('tr') : [];
        if (rows.length === 0) return;

        var valorTotal = window.FormatadoresFinancas
            ? window.FormatadoresFinancas.paraFloat(this.el.valorTotal.value)
            : 0;
        var n = rows.length;
        var valorBase = Math.floor((valorTotal / n) * 100) / 100;
        var resto = parseFloat((valorTotal - (valorBase * n)).toFixed(2));

        var dataEmissao = this.el.dataEmissao ? this.el.dataEmissao.value : '';
        var intervalo = this.el.intervaloDias ? (parseInt(this.el.intervaloDias.value) || 30) : 30;
        var dataBase = dataEmissao ? new Date(dataEmissao + 'T00:00:00') : new Date();

        rows.forEach(function(row, idx) {
            var inputValor = row.querySelector('.js-parcela-valor');
            if (inputValor) {
                var v = (idx === 0) ? (valorBase + resto) : valorBase;
                inputValor.value = v.toFixed(2).replace('.', ',');
            }

            var inputData = row.querySelector('.js-parcela-data');
            if (inputData) {
                var d = new Date(dataBase.getTime());
                d.setDate(d.getDate() + ((idx + 1) * intervalo));
                var ano = d.getFullYear();
                var mes = String(d.getMonth() + 1).padStart(2, '0');
                var dia = String(d.getDate()).padStart(2, '0');
                inputData.value = ano + '-' + mes + '-' + dia;
            }
        });

        this._parcelasCarregadas = null;
        this._datasEditadasManualmente = false;
        this._atualizarTotalizadores();
    };

    // ==========================================================
    // HELPER: FormData para o backend no modo create
    // ==========================================================
    TransacaoForm.prototype._toFormData = function(data) {
        var fd = new FormData();
        fd.append('tipo', data.tipo);
        fd.append('descricao', data.descricao);
        fd.append('categoria_id', data.categoria_id || '');
        fd.append('valor_total', data.valor_total);
        fd.append('data_emissao', data.data_emissao);
        fd.append('data_vencimento', data.data_vencimento);
        fd.append('total_parcelas', data.total_parcelas);
        fd.append('intervaloDias', data.intervaloDias);
        fd.append('primeiroVencimento', data.primeiroVencimento);

        (data.parcelas || []).forEach(function(p, i) {
            fd.append('parcela_valor_' + (i + 1), p.valor);
            fd.append('parcela_vencimento_' + (i + 1), p.vencimento);
        });

        return fd;
    };

    // ==========================================================
    // TOTALIZADOR
    // ==========================================================
    TransacaoForm.prototype._atualizarTotalizadores = function() {
        var totalParcelas = this.el.totalParcelas ? (parseInt(this.el.totalParcelas.value) || 1) : 1;
        var valorTotal = this.el.valorTotal && window.FormatadoresFinancas
            ? window.FormatadoresFinancas.paraFloat(this.el.valorTotal.value)
            : 0;

        var fmt = function(v) {
            return 'R$ ' + v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        };

        var soma = 0;
        if (this.el.parcelasBody) {
            this.el.parcelasBody.querySelectorAll('.js-parcela-valor').forEach(function(inp) {
                soma += window.FormatadoresFinancas
                    ? window.FormatadoresFinancas.paraFloat(inp.value)
                    : parseFloat(inp.value) || 0;
            });
        }

        var diferenca = valorTotal - soma;
        var mostrarSoma = totalParcelas > 1;

        if (this.el.totalOriginal) this.el.totalOriginal.textContent = fmt(valorTotal);
        if (this.el.somaParcelas)  this.el.somaParcelas.textContent  = fmt(soma);
        if (this.el.diferenca)     this.el.diferenca.textContent     = fmt(diferenca);

        if (this.el.totalOriginal) {
            var blocoTotal = this.el.totalOriginal.closest('.total-item-footer');
            if (blocoTotal) blocoTotal.style.display = '';
        }

        if (this.el.somaParcelas) {
            var blocoSoma = this.el.somaParcelas.closest('.total-item-footer');
            if (blocoSoma) blocoSoma.style.display = mostrarSoma ? '' : 'none';
        }

        if (this.el.diferenca) {
            var blocoDif = this.el.diferenca.closest('.total-item-footer');
            if (blocoDif) {
                blocoDif.style.display = mostrarSoma ? '' : 'none';

                // 🔥 Pinta de vermelho se a diferença não bate
                if (mostrarSoma && Math.abs(diferenca) > 0.01) {
                    blocoDif.style.color = '#ef4444';
                    this.el.diferenca.style.color = '#ef4444';
                } else {
                    blocoDif.style.color = '';
                    this.el.diferenca.style.color = '';
                }
            }
        }
    };

    // ==========================================================
    // Exposição global
    // ==========================================================
    window.TransacaoForm = TransacaoForm;

    console.log('✅ TransacaoForm carregado!');
})();

// ==== totalizadores.js ====
// static/js/modules/pasta_financas/components/totalizadores.js
// totalizadores.js - VERSÃO SIMPLIFICADA E CORRIGIDA

function calcularTotaisFinancas() {
    const linhas = document.querySelector('.custom-table tbody')?.children || [];
    let totalReceitas = 0;
    let totalDespesas = 0;

    for (let i = 0; i < linhas.length; i++) {
        const linha = linhas[i];
        if (linha.querySelector('td[colspan]')) continue;

        const colunas = linha.cells;
        if (colunas.length < 3) continue;

        const tipo = colunas[1]?.innerText || '';
        const valorTexto = colunas[2]?.innerText || 'R$ 0,00';

        let valor = parseFloat(valorTexto.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()) || 0;

        if (tipo.includes('Receita')) totalReceitas += valor;
        else if (tipo.includes('Despesa')) totalDespesas += valor;
    }

    const saldo = totalReceitas - totalDespesas;
    const formatar = (v) => `R$ ${v.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`;

    const elReceitas = document.getElementById('totalReceitas');
    const elDespesas = document.getElementById('totalDespesas');
    const elSaldo = document.getElementById('totalSaldo');

    if (elReceitas) elReceitas.innerHTML = formatar(totalReceitas);
    if (elDespesas) elDespesas.innerHTML = formatar(totalDespesas);
    if (elSaldo) elSaldo.innerHTML = formatar(saldo);
}

// ==========================================================
// 🔥 INICIALIZAÇÃO
// ==========================================================

// 1. Quando a página carregar
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
        setTimeout(calcularTotaisFinancas, 100);
    });
} else {
    setTimeout(calcularTotaisFinancas, 100);
}

// 2. 🔥 ÚNICO listener — afterRequest (SEMPRE dispara, mesmo com tbody)
//    Cobre: filtros, excluir, reativar, quitar, estornar, inserir, editar
document.body.addEventListener('htmx:afterRequest', function(evt) {
    const target = evt.detail.target;
    if (!target) return;

    const path = evt.detail.pathInfo?.requestPath || '';

    const alvoRelevante = (
        target.id === 'tabela-container' ||
        target.id === 'tbody-transacoes' ||
        target.closest('#tabela-container') ||
        path.includes('/financas') ||
        path.includes('/excluir') ||
        path.includes('/reativar') ||
        path.includes('/quitar') ||
        path.includes('/estornar')
    );

    if (alvoRelevante) {
        // 🔥 50ms garante que o swap do tbody terminou
        setTimeout(calcularTotaisFinancas, 50);
    }
});

console.log('✅ Totalizadores carregados e monitorando mudanças!');

// ==== botoes_outros_filtros.js ====
// static/js/modules/pasta_financas/components/botoes_outros_filtros.js
// ==========================================================
// Atualiza visual dos botões de filtro após HTMX
// ==========================================================

(function() {
    'use strict';

    function atualizarBotoesTransacao() {
        const input = document.getElementById('mostrar_inativas_input');
        if (!input) return;

        const valor = input.value;   // '0' | '1' | '2'
        if (!valor) return;

        // Remove active de todos (usa .btn-filter, não .btn-pure)
        document.querySelectorAll('#botoes-transacao .btn-filter').forEach(function(btn) {
            btn.classList.remove('btn-active-toggle');
        });

        // Encontra o botão ativo pelo atributo hx-vals
        const botaoAtivo = document.querySelector(
            '#botoes-transacao button[hx-vals*=\'mostrar_inativas": "' + valor + '"\']'
        );
        if (botaoAtivo) botaoAtivo.classList.add('btn-active-toggle');
    }

    // 🔥 Após HTMX substituir a tabela
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        const target = evt.detail.target;
        if (!target) return;

        if (target.id === 'tabela-container' ||
            target.id === 'mostrar_inativas_input' ||
            target.closest('#tabela-container')) {
            setTimeout(atualizarBotoesTransacao, 0);
        }
    });

    // 🔥 Após qualquer request HTMX (fallback)
    document.body.addEventListener('htmx:afterRequest', function(evt) {
        const target = evt.detail.target;
        if (!target) return;

        if (target.id === 'tabela-container' ||
            target.id === 'mostrar_inativas_input' ||
            target.closest('#tabela-container')) {
            setTimeout(atualizarBotoesTransacao, 50);
        }
    });

    console.log('✅ botoes_outros_filtros carregado!');
})();

// ==== ordenacao.js ====
// ORDENAÇÃO DE COLUNAS - VERSÃO OTIMIZADA
(function() {
    'use strict';
    
    let colunaAtual = null;
    let ordemAtual = 'asc';
    let cacheValores = new Map();
    
    function getValorParaComparacao(celula, tipo) {
        const texto = celula?.innerText?.trim() || '';
        const cacheKey = `${tipo}_${texto}`;
        
        if (cacheValores.has(cacheKey)) return cacheValores.get(cacheKey);
        
        let valor;
        if (tipo === 'numero') {
            valor = parseFloat(texto.replace('R$', '').replace(/\./g, '').replace(',', '.')) || 0;
        } else if (tipo === 'data') {
            if (texto && texto !== '-') {
                const partes = texto.split('/');
                valor = partes.length === 3 ? new Date(partes[2], partes[1] - 1, partes[0]) : new Date(0);
            } else {
                valor = new Date(0);
            }
        } else {
            valor = (texto || '').toLowerCase();
        }
        
        cacheValores.set(cacheKey, valor);
        return valor;
    }
    
    function ordenarTabela(colunaIndex, tipo) {
        const tbody = document.querySelector('.custom-table tbody');
        if (!tbody) return;
        
        const linhas = Array.from(tbody.querySelectorAll('tr'));
        const linhasValidas = linhas.filter(row => !row.querySelector('td[colspan]'));
        const linhasMensagem = linhas.filter(row => row.querySelector('td[colspan]'));
        
        if (colunaAtual !== colunaIndex) cacheValores.clear();
        
        const linhasComValor = linhasValidas.map(linha => ({
            linha: linha,
            valor: getValorParaComparacao(linha.children[colunaIndex], tipo)
        }));
        
        linhasComValor.sort((a, b) => {
            if (a.valor < b.valor) return ordemAtual === 'asc' ? -1 : 1;
            if (a.valor > b.valor) return ordemAtual === 'asc' ? 1 : -1;
            return 0;
        });
        
        const fragment = document.createDocumentFragment();
        linhasComValor.forEach(item => fragment.appendChild(item.linha));
        linhasMensagem.forEach(row => fragment.appendChild(row));
        
        tbody.innerHTML = '';
        tbody.appendChild(fragment);
    }
    
    function initOrdenacao() {
        const cabecalhos = document.querySelectorAll('.custom-table th');
        const tiposColunas = [
            { index: 0, tipo: 'numero' },
            { index: 1, tipo: 'texto' },
            { index: 2, tipo: 'numero' },
            { index: 3, tipo: 'texto' },
            { index: 4, tipo: 'texto' },
            { index: 5, tipo: 'texto' },
            { index: 6, tipo: 'data' },
            { index: 7, tipo: 'data' }
        ];
        
        cabecalhos.forEach((th, idx) => {
            const colunaInfo = tiposColunas.find(c => c.index === idx);
            if (!colunaInfo) return;
            
            th.classList.add('sortable');
            
            th.addEventListener('click', () => {
                cabecalhos.forEach(h => h.classList.remove('asc', 'desc'));
                
                if (colunaAtual === idx) {
                    ordemAtual = ordemAtual === 'asc' ? 'desc' : 'asc';
                } else {
                    colunaAtual = idx;
                    ordemAtual = 'asc';
                }
                
                th.classList.add(ordemAtual === 'asc' ? 'asc' : 'desc');
                ordenarTabela(idx, colunaInfo.tipo);
            });
        });
    }
    
    function reinitOrdenacao() {
        cacheValores.clear();
        colunaAtual = null;
        ordemAtual = 'asc';
        initOrdenacao();
    }
    
    // Inicialização
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initOrdenacao);
    } else {
        initOrdenacao();
    }
    
    // 🔥 CORRIGIDO: document.addEventListener (não document.body)
    document.addEventListener('htmx:afterSwap', function(evento) {
        if (evento.detail.target?.id === 'tabela-container') {
            reinitOrdenacao();
        }
    });
    
})();

// ==== transacao-nova.js ====
// ==========================================================
// MODAL NOVA TRANSAÇÃO - v2 (usa TransacaoForm)
// ==========================================================
(function() {
    'use strict';

    var formInstance = null;

    function instanciar() {
        var formEl = document.getElementById('formNovaTransacao');
        if (!formEl) return null;
        if (formInstance) return formInstance;

        formInstance = new window.TransacaoForm(formEl, {
            mode: 'create',
            onSubmitSuccess: function(result) {
                if (window.Notificacao) window.Notificacao.sucesso(result.message || 'Transação salva!');
                fecharModalNovaTransacao();

                // Recarrega tabela via HTMX
                if (window.recarregarTabelaFinancas) {
                    window.recarregarTabelaFinancas();
                } else if (window.htmx) {
                    htmx.ajax('GET', '/financas', '#tabela-container');
                } else {
                    setTimeout(function() { window.location.reload(); }, 600);
                }
            }
        });
        return formInstance;
    }

    function abrirModalNovaTransacao() {
        var modal = document.getElementById('modalNovaTransacao');
        if (!modal) return;

        var f = instanciar();
        if (f) f.reset();

        modal.classList.add('active');
        modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';

        setTimeout(function() {
            var desc = modal.querySelector('.js-descricao');
            if (desc) desc.focus();
        }, 100);
    }

    function fecharModalNovaTransacao() {
        var modal = document.getElementById('modalNovaTransacao');
        if (modal) {
            modal.classList.remove('active');
            modal.style.display = 'none';
        }
        document.body.style.overflow = '';
        var f = instanciar();
        if (f) f.reset();
    }

    function salvarNovaTransacao() {
        var f = instanciar();
        if (!f) return;

        var btn = document.querySelector('#footerFixoNova .btn-footer-primary');
        if (btn) { btn.disabled = true; btn.dataset.txt = btn.innerHTML; btn.innerHTML = 'Salvando...'; }

        f.submit('/financas/nova_transacao/salvar')
         .catch(function() { /* já notificado */ })
         .finally(function() {
            if (btn) { btn.disabled = false; btn.innerHTML = btn.dataset.txt || 'SALVAR'; }
         });
    }

    window.abrirModalNovaTransacao = abrirModalNovaTransacao;
    window.fecharModalNovaTransacao = fecharModalNovaTransacao;
    window.salvarNovaTransacao = salvarNovaTransacao;

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var modal = document.getElementById('modalNovaTransacao');
            if (modal && modal.classList.contains('active')) fecharModalNovaTransacao();
        }
    });

    document.addEventListener('click', function(e) {
        var modal = document.getElementById('modalNovaTransacao');
        if (modal && modal.classList.contains('active') && e.target === modal) fecharModalNovaTransacao();
    });

    console.log('✅ MODAL NOVA TRANSAÇÃO v2 carregado!');
})();

// ==== transacao-editar.js ====
// static\js\modules\pasta_financas\modals\transacao-editar.js

// ==========================================================
// MODAL EDITAR TRANSAÇÃO - v3 (HTMX injeta, JS popula)
// ==========================================================
(function() {
    'use strict';

    var transacaoId = null;
    var formInstance = null;

    function instanciar(formEl) {
        if (!formEl) return null;
        if (formInstance && formInstance.form === formEl) return formInstance;

        formInstance = new window.TransacaoForm(formEl, {
            mode: 'edit',
            onSubmitSuccess: function(result) {
                if (window.Notificacao) window.Notificacao.sucesso(result.message || 'Transação atualizada!');
                fecharModalEditarTransacao();

                // 🔥 Recarrega só a tabela via HTMX
                if (window.recarregarTabelaFinancas) {
                    window.recarregarTabelaFinancas();
                } else if (window.htmx) {
                    htmx.ajax('GET', '/financas', '#tabela-container');
                } else {
                    setTimeout(function() { window.location.reload(); }, 600);
                }
            }
        });
        return formInstance;
    }

    // ==========================================================
    // ABRIR (busca dados via /dados/ e popula)
    // ==========================================================
    function abrirModalEditarTransacao(id) {
        transacaoId = id;

        var modal = document.getElementById('modalEditarTransacao');
        var formEl = document.getElementById('formEditarTransacao');
        if (!modal || !formEl) return;

        if (!transacaoId) {
            if (window.Notificacao) window.Notificacao.erro('ID da transação não identificado.');
            return;
        }

        modal.classList.add('active');
        modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';

        // Spinner
        var body = modal.querySelector('.fin-modal-body');
        var loadingDiv = null;
        if (body) {
            loadingDiv = document.createElement('div');
            loadingDiv.id = 'editLoadingOverlay';
            loadingDiv.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);display:flex;justify-content:center;align-items:center;flex-direction:column;z-index:10;border-radius:8px;';
            loadingDiv.innerHTML = '<div style="width:40px;height:40px;border:4px solid #fff;border-top-color:#2563eb;border-radius:50%;animation:spin 0.8s linear infinite;"></div><p style="color:#fff;margin-top:10px;">Carregando dados...</p>';
            body.style.position = 'relative';
            body.appendChild(loadingDiv);
        }

        fetch('/financas/edit_transacoes/dados/' + transacaoId, {
            method: 'GET',
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(function(r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function(resposta) {
            if (loadingDiv) loadingDiv.remove();
            var data = resposta.data || resposta;

            // Atualiza título
            var seqSpan = modal.querySelector('#finEditarSequencia');
            if (seqSpan && data.sequencia) {
                seqSpan.textContent = 'Editar Transação #' + data.sequencia;
            }
            if (formEl && data.sequencia) {
                formEl.dataset.transacaoId = data.sequencia;
            }

            // Popula form
            var f = instanciar(formEl);
            if (f) f.setData(data);
        })
        .catch(function(error) {
            console.error('❌ Erro no GET dados:', error);
            if (loadingDiv) loadingDiv.remove();
            if (body) body.innerHTML = '<div style="color:#ef4444;padding:20px;">Erro ao carregar dados</div>';
        });
    }

    // ==========================================================
    // FECHAR
    // ==========================================================
    function fecharModalEditarTransacao() {
        var modal = document.getElementById('modalEditarTransacao');
        if (modal) {
            modal.classList.remove('active');
            modal.style.display = 'none';
        }
        document.body.style.overflow = '';
        formInstance = null;
    }

    // ==========================================================
    // SALVAR
    // ==========================================================
    function salvarEditarTransacao() {
        var formEl = document.getElementById('formEditarTransacao');
        transacaoId = (formEl && formEl.dataset.transacaoId) || transacaoId;

        if (!transacaoId || transacaoId === 'None') {
            if (window.Notificacao) window.Notificacao.erro('ID da transação não identificado.');
            return;
        }

        var f = instanciar(formEl);
        if (!f) return;

        var btn = document.querySelector('#footerFixoEditar .btn-footer-primary');
        if (btn) { btn.disabled = true; btn.dataset.txt = btn.innerHTML; btn.innerHTML = 'Salvando...'; }

        f.submit('/financas/edit_transacoes/' + transacaoId)
         .catch(function() { /* já notificado */ })
         .finally(function() {
            if (btn) { btn.disabled = false; btn.innerHTML = btn.dataset.txt || 'ATUALIZAR'; }
         });
    }

    // ==========================================================
    // 🔥 O FIX: escuta o HTMX injetar o modal e chama abrir()
    // ==========================================================
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        var target = evt.detail && evt.detail.target;
        if (!target) return;
        if (target.id !== 'modal-editar-container' && !target.closest('#modal-editar-container')) return;

        var formEl = document.getElementById('formEditarTransacao');
        if (!formEl) return;

        var seq = formEl.dataset.transacaoId;
        if (!seq || seq === 'None') {
            console.warn('⚠️ HTMX injetou o modal mas sem data-transacao-id');
            return;
        }

        console.log('🔁 HTMX injetou modal de editar, populando via /dados/' + seq);
        abrirModalEditarTransacao(seq);
    });

    window.abrirModalEditarTransacao = abrirModalEditarTransacao;
    window.fecharModalEditarTransacao = fecharModalEditarTransacao;
    window.salvarEditarTransacao = salvarEditarTransacao;

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var modal = document.getElementById('modalEditarTransacao');
            if (modal && modal.classList.contains('active')) fecharModalEditarTransacao();
        }
    });

    document.addEventListener('click', function(e) {
        var modal = document.getElementById('modalEditarTransacao');
        if (modal && modal.classList.contains('active') && e.target === modal) fecharModalEditarTransacao();
    });

    console.log('✅ MODAL EDITAR TRANSAÇÃO v3 carregado!');
})();

// ==== detalhes_completo.js ====
function verDetalhesTransacao(transacaoId) {
    const modal = document.getElementById('modalDetalhesTransacao');
    const conteudo = document.getElementById('conteudoDetalhesTransacao');
    
    conteudo.innerHTML = `
        <div style="text-align: center; padding: 30px; color: var(--texto-mutado);">
            <div class="spinner-pure"></div>
            <p style="margin-top: 10px; font-size: var(--fs-micro);">Carregando dados da transação...</p>
        </div>
    `;
    
    modal.classList.add('active');
    
    fetch(`/financas/detalhes/${transacaoId}`)
        .then(response => response.json())
        .then(data => {
            if (data.error) {
                conteudo.innerHTML = `<div class="badge-pure bg-danger" style="width: 100%; padding: 10px;">${data.error}</div>`;
                return;
            }
            
            const tipoIcon = data.tipo === 'receita' ? '📈' : '📉';
            
            // ✅ CORRIGIDO: verifica se o elemento existe
            const tituloElement = document.getElementById('modalTituloTransacao');
            const tituloTexto = `${tipoIcon} ${data.descricao.substring(0, 50)}`;
            
            if (tituloElement) {
                tituloElement.innerHTML = tituloTexto;
            } else {
                // Fallback: cria o elemento no header
                const header = document.querySelector('.modal-detalhes-header');
                if (header) {
                    const span = document.createElement('span');
                    span.className = 'modal-detalhes-title';
                    span.id = 'modalTituloTransacao';
                    span.innerHTML = tituloTexto;
                    header.insertBefore(span, header.querySelector('.modal-detalhes-close'));
                }
            }
            
            conteudo.innerHTML = `
                <div class="modal-detalhes-field full-width" style="margin-bottom: 12px;">
                    <div class="field-detalhes-label" style="color: var(--cor-marca); font-weight: 600;">💰 Descrição</div>
                    <div class="field-detalhes-value-scroll" style="font-size: var(--fs-pequeno);">${data.descricao}</div>
                </div>
                
                <div class="modal-detalhes-grid" style="font-size: var(--fs-pequeno);">
                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📊 Tipo</div>
                        <div class="field-detalhes-value"><span class="badge-pure ${data.tipo === 'receita' ? 'bg-success' : 'bg-warning text-dark'}">${data.tipo_label}</span></div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">💰 Valor</div>
                        <div class="field-detalhes-value" style="font-weight: bold; font-size: 1.1rem;">${data.valor}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📊 Status</div>
                        <div class="field-detalhes-value"><span class="badge-pure ${data.status === 'aberto' ? 'bg-danger' : 'bg-success'}">${data.status_label}</span></div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">🏷️ Categoria</div>
                        <div class="field-detalhes-value">
                            <span class="badge-pure" style="background-color: ${data.categoria_cor || 'var(--border-sutil)'}; color: white;">
                                ${data.categoria}
                            </span>
                        </div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📅 Data Emissão</div>
                        <div class="field-detalhes-value">${data.data_emissao}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">⏰ Data Vencimento</div>
                        <div class="field-detalhes-value">${data.data_vencimento}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">✅ Data Quitação</div>
                        <div class="field-detalhes-value">${data.data_quitamento}</div>
                    </div>

                    <div class="modal-detalhes-field">
                        <div class="field-detalhes-label">📦 Parcela</div>
                        <div class="field-detalhes-value">${data.parcela_label}</div>
                    </div>
                </div>
            `;
        })
        .catch(error => {
            console.error('Erro:', error);
            conteudo.innerHTML = `<div class="badge-pure bg-danger" style="width: 100%; padding: 10px;">Erro ao carregar detalhes</div>`;
        });
}

function fecharModalDetalhesTransacao(event) {
    if (!event || event.target.classList.contains('modal-detalhes-overlay')) {
        document.getElementById('modalDetalhesTransacao').classList.remove('active');
    }
}

// Fechar modal com tecla ESC
document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape') {
        const modal = document.getElementById('modalDetalhesTransacao');
        if (modal && modal.classList.contains('active')) {
            fecharModalDetalhesTransacao(null);
        }
    }
});

// ==== excluir_financas.js ====
// static/js/modules/pasta_financas/acoes_e_modais/pasta_excluir/excluir_financas.js
// ==========================================================
// EXCLUIR (inativar) — HTMX puro
// ==========================================================

(function() {
    'use strict';

    let modalAberto = false;

    // ==========================================================
    // Abrir o modal
    // ==========================================================
    window.abrirModalExcluir = function(config) {
        if (modalAberto) return;

        const modal = document.getElementById('modalExcluirFinancas');
        const titulo = document.getElementById('modalExcluirTitulo');
        const texto = document.getElementById('modalExcluirTexto');

        // 🔥 Clona botão pra limpar listeners HTMX antigos
        let btnConfirmar = document.getElementById('btnConfirmarExcluirFinancas');
        if (btnConfirmar && btnConfirmar.parentNode) {
            const clone = btnConfirmar.cloneNode(true);
            btnConfirmar.parentNode.replaceChild(clone, btnConfirmar);
            btnConfirmar = clone;
        }

        const btnCancelar = document.getElementById('btnCancelarExcluirFinancas');

        if (!modal || !btnConfirmar || !btnCancelar) {
            console.error('❌ Modal de exclusão não encontrado');
            return;
        }

        modalAberto = true;
        titulo.textContent = config.titulo;
        texto.textContent = config.texto;
        modal.classList.add('active');

        // Configura hx-post dinamicamente
        btnConfirmar.setAttribute('hx-post', config.url);
        btnConfirmar.setAttribute('hx-target', '#tbody-transacoes');
        btnConfirmar.setAttribute('hx-swap', 'outerHTML');

        if (window.htmx) window.htmx.process(btnConfirmar);

        const fecharModal = () => {
            modal.classList.remove('active');
            modalAberto = false;
        };

        btnCancelar.onclick = fecharModal;
        modal.onclick = function(e) {
            if (e.target === modal) fecharModal();
        };

        // Fecha se sucesso (200/204) OU se 409 (conflict → tratado por evento)
        btnConfirmar.addEventListener('htmx:afterRequest', function onDone(evt) {
            const status = evt.detail.xhr.status;
            if (status >= 200 && status < 300) {
                fecharModal();
            } else if (status === 409) {
                // Deixa o listener global tratar
                fecharModal();
            }
            btnConfirmar.removeEventListener('htmx:afterRequest', onDone);
        });
    };

    // ==========================================================
    // Delegação: clique no botão Excluir da linha
    // ==========================================================
    document.addEventListener('click', function(e) {
        const btn = e.target.closest('.btn-excluir');
        if (!btn) return;

        e.preventDefault();

        // 🔥 Zera o estado (garante que a 2ª vez funcione)
        modalAberto = false;

        const id = btn.dataset.id;
        const descricao = btn.dataset.desc;

        window.abrirModalExcluir({
            titulo: 'Inativar Transação',
            texto: 'Deseja inativar a transação: "' + descricao + '"?',
            url: '/financas/excluir_transacao/' + id
        });
    });

    // ==========================================================
    // Backend dispara isso via HX-Trigger quando é parcelamento
    // ==========================================================
    document.body.addEventListener('pedirConfirmacaoParcelamento', function(evt) {
        const dados = evt.detail;
        if (!dados || !dados.pai_id) return;

        // 🔥 Zera o estado (o 1º modal já fechou)
        modalAberto = false;

        // Abre 2º modal perguntando se quer inativar tudo
        setTimeout(function() {
            window.abrirModalExcluir({
                titulo: '⚠️ Atenção! Parcelamento Detectado',
                texto: 'Esta transação faz parte de um parcelamento.\n\nDeseja inativar TODAS as parcelas?',
                url: '/financas/excluir_transacao/parcelamento/' + dados.pai_id
            });
        }, 200);
    });

    // ==========================================================
    // Toast via HX-Trigger
    // ==========================================================
    document.body.addEventListener('transacaoInativada', function() {
        modalAberto = false;
        const modal = document.getElementById('modalExcluirFinancas');
        if (modal) modal.classList.remove('active');

        if (window.Notificacao) window.Notificacao.sucesso('Transação inativada com sucesso!');
        if (typeof calcularTotaisFinancas === 'function') calcularTotaisFinancas();
    });

    console.log('✅ Sistema de exclusão (HTMX) carregado!');
})();

// ==== modal_estornar_quitado.js ====
// static/js/modules/pasta_financas/acoes_e_modais/pasta_estornar/modal_estornar_quitado.js
// ==========================================================
// MODAL ESTORNAR — HTMX puro
// ==========================================================

(function() {
    'use strict';

    if (window._estornoSistemaCarregado) return;
    window._estornoSistemaCarregado = true;

    let modalAberto = false;

    // ==========================================================
    // Abrir o modal
    // ==========================================================
    window.abrirModalEstornar = function(config) {
        if (modalAberto) return;

        const modal = document.getElementById('modalEstornar');
        const titulo = document.getElementById('modalEstornarTitulo');
        const texto = document.getElementById('modalEstornarTexto');
        const btnConfirmar = document.getElementById('btnConfirmarEstornar');
        const btnCancelar = document.getElementById('btnCancelarEstornar');

        if (!modal || !btnConfirmar || !btnCancelar) return;

        modalAberto = true;

        titulo.textContent = config.titulo;
        texto.textContent = config.texto;
        modal.classList.add('active');

        // 🔥 Define a URL do hx-post dinamicamente
        btnConfirmar.setAttribute('hx-post', '/financas/estornar_transacao/' + config.id);
        btnConfirmar.setAttribute('hx-target', '#linha-transacao-' + config.id);
        btnConfirmar.setAttribute('hx-swap', 'outerHTML');

        // 🔥 Processa HTMX no botão (senão ele ignora atributos novos)
        if (window.htmx) window.htmx.process(btnConfirmar);

        const fecharModal = () => {
            modal.classList.remove('active');
            modalAberto = false;
            btnConfirmar.removeAttribute('hx-post');
            btnConfirmar.removeAttribute('hx-target');
        };

        btnCancelar.onclick = fecharModal;
        modal.onclick = function(e) {
            if (e.target === modal) fecharModal();
        };

        // Fechar após sucesso (HTMX dispara htmx:afterRequest)
        btnConfirmar.addEventListener('htmx:afterRequest', function onDone(evt) {
            if (evt.detail.successful) {
                fecharModal();
                btnConfirmar.removeEventListener('htmx:afterRequest', onDone);
            }
        });
    };

    // ==========================================================
    // Delegação: clique no botão Estornar da linha
    // ==========================================================
    document.addEventListener('click', function(e) {
        const btn = e.target.closest('.btn-estornar');
        if (!btn) return;

        e.preventDefault();

        const id = btn.dataset.id;
        const descricao = btn.dataset.desc;
        const tipo = btn.dataset.tipo;
        const tipoTexto = tipo === 'despesa' ? 'DESPESA' : 'RECEITA';

        window.abrirModalEstornar({
            id: id,
            titulo: '⚠️ Estornar ' + tipoTexto,
            texto: 'Deseja realmente ESTORNAR a transação?\n\n"' + descricao + '"\n\nEla voltará para o status ABERTO.'
        });
    });

    // ==========================================================
    // Toast quando o backend dispara HX-Trigger
    // ==========================================================
    document.body.addEventListener('transacaoEstornada', function() {
        if (window.Notificacao) {
            window.Notificacao.sucesso('Transação estornada com sucesso!');
        }
        if (typeof calcularTotaisFinancas === 'function') {
            calcularTotaisFinancas();
        }
    });

    console.log('✅ Sistema de estorno (HTMX) carregado!');
})();

